     def fts_search_raw(self, fts_query: str, limit: int = 100) -> list[tuple[int, float]]:
         """Execute a pre-built FTS5 query (no escaping/tokenization)."""
         if not fts_query:
             return []
         rows = self._conn.execute(
             f"SELECT chunks_fts.rowid, -bm25(chunks_fts, {_FTS_WEIGHTS}) AS score "
             f"FROM chunks_fts WHERE chunks_fts MATCH ? ORDER BY score DESC LIMIT ?",
             (fts_query, limit),
         ).fetchall()
         return [(r[0], r[1]) for r in rows]
